package cl.acis.ordenes.service;
import cl.acis.ordenes.dto.*; import cl.acis.ordenes.exception.*; import cl.acis.ordenes.model.*; import cl.acis.ordenes.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import java.util.stream.*;
@Service @Transactional public class OrdenService { final OrdenRepository repo;final EventoOrdenRepository eventos;final ReglasOrden reglas; public OrdenService(OrdenRepository r,EventoOrdenRepository e,ReglasOrden g){repo=r;eventos=e;reglas=g;}
 public OrdenResponse crear(OrdenRequest r,Long actor){OrdenTrabajo o=new OrdenTrabajo();o.setCodigo(siguiente());o.setClienteId(r.clienteId());o.setEquipoId(r.equipoId());o.setTipoServicio(r.tipoServicio());o.setPrioridad(r.prioridad());o.setSlaHoras(sla(r.prioridad()));o.setFechaProgramada(r.fechaProgramada());o.setDescripcion(r.descripcion());o.setComentarioCliente(r.comentarioCliente());o.setCreadoPorId(actor);repo.save(o);eventos.save(new EventoOrden(o,TipoEvento.CREACION,null,EstadoOrden.CREADA,actor,"Orden creada"));return dto(o);}
 public List<OrdenResponse> listar(EstadoOrden estado,Long tecnico,Long cliente,LocalDate fecha,Prioridad prioridad,ActorFilter f){return repo.findAll().stream().filter(o->estado==null||o.getEstado()==estado).filter(o->tecnico==null||tecnico.equals(o.getTecnicoId())).filter(o->cliente==null||cliente.equals(o.getClienteId())).filter(o->prioridad==null||prioridad==o.getPrioridad()).filter(o->fecha==null||o.getFechaProgramada()!=null&&o.getFechaProgramada().toLocalDate().equals(fecha)).filter(o->visible(o,f)).map(this::dto).toList();}
 public OrdenResponse obtener(Long id,ActorFilter f){OrdenTrabajo o=get(id);if(!visible(o,f))throw new ProhibidoException("No puedes ver esta orden");return dto(o);} public List<EventoResponse> eventos(Long id){return eventos.findByOrdenOrderByFechaAsc(get(id)).stream().map(e->new EventoResponse(e.getId(),e.getTipo(),e.getEstadoAnterior(),e.getEstadoNuevo(),e.getActorId(),e.getDetalle(),e.getFecha())).toList();} public Set<AccionOrden> disponibles(Long id,String rol,Long actor){return reglas.disponibles(get(id),rol,actor);}
 public OrdenResponse editar(Long id,OrdenRequest r,Long actor,String rol){if(!rol.equals("ADMINISTRADOR")&&!rol.equals("JEFATURA"))throw new ProhibidoException("Solo JEFATURA o ADMINISTRADOR puede editar");OrdenTrabajo o=get(id);o.setClienteId(r.clienteId());o.setEquipoId(r.equipoId());o.setTipoServicio(r.tipoServicio());o.setPrioridad(r.prioridad());o.setSlaHoras(sla(r.prioridad()));o.setFechaProgramada(r.fechaProgramada());o.setDescripcion(r.descripcion());o.setComentarioCliente(r.comentarioCliente());eventos.save(new EventoOrden(o,TipoEvento.EDICION,o.getEstado(),o.getEstado(),actor,"Datos editados"));return dto(o);}
 public void eliminar(Long id,Long actor,String rol){if(!rol.equals("ADMINISTRADOR")&&!rol.equals("JEFATURA"))throw new ProhibidoException("Solo JEFATURA o ADMINISTRADOR puede eliminar");OrdenTrabajo o=get(id);if(o.getEstado()!=EstadoOrden.CREADA)throw new ReglaNegocioException("Solo se puede eliminar una OT CREADA");eventos.save(new EventoOrden(o,TipoEvento.ELIMINACION,EstadoOrden.CREADA,null,actor,"Orden eliminada"));repo.delete(o);}
 public OrdenResponse accion(Long id,AccionRequest r,String rol,Long actor){OrdenTrabajo o=get(id);reglas.exigir(o,r.accion(),rol,actor);EstadoOrden antes=o.getEstado();String det=r.motivo();switch(r.accion()){case ASIGNAR->asignar(o,r,actor);case ACEPTAR->o.setEstado(EstadoOrden.ACEPTADA);case RECHAZAR-> {o.setEstado(EstadoOrden.CREADA);o.setTecnicoId(null);}case CHECK_IN-> {o.setEstado(EstadoOrden.EN_EJECUCION);o.setCheckInEn(LocalDateTime.now());o.setCheckInLat(r.lat());o.setCheckInLon(r.lon());}case CHECK_OUT->{if(r.diagnostico()==null||r.diagnostico().isBlank()||r.actividades()==null||r.actividades().isBlank()||r.cantidadFotosEvidencia()==null||r.cantidadFotosEvidencia()<1)throw new ReglaNegocioException("CHECK_OUT exige diagnóstico, actividades y al menos una foto de evidencia");/* Simplificación: se valida un contador local; luego se consultaría ms-catalogos. */o.setEstado(EstadoOrden.CERRADA);o.setCheckOutEn(LocalDateTime.now());o.setCheckOutLat(r.lat());o.setCheckOutLon(r.lon());o.setDiagnostico(r.diagnostico());o.setActividades(r.actividades());o.setMateriales(r.materiales());}case VALIDAR->o.setEstado(EstadoOrden.VALIDADA);case OBSERVAR->{if(r.motivo()==null||r.motivo().isBlank())throw new ReglaNegocioException("OBSERVAR exige un comentario");o.setEstado(EstadoOrden.OBSERVADA);}case REABRIR->{det="Atención anterior: diagnóstico="+o.getDiagnostico()+", actividades="+o.getActividades()+", materiales="+o.getMateriales();o.setEstado(EstadoOrden.ASIGNADA);o.setDiagnostico(null);o.setActividades(null);o.setMateriales(null);}case REPROGRAMAR->reprogramar(o,r);case CANCELAR->{if(r.motivo()==null||r.motivo().isBlank())throw new ReglaNegocioException("CANCELAR exige un motivo");o.setEstado(EstadoOrden.CANCELADA);}}repo.save(o);eventos.save(new EventoOrden(o,tipo(r.accion()),antes,o.getEstado(),actor,det));return dto(o);}
 private void asignar(OrdenTrabajo o,AccionRequest r,Long actor){if(r.tecnicoId()==null)throw new ReglaNegocioException("ASIGNAR exige técnico");LocalDate d=Optional.ofNullable(o.getFechaProgramada()).orElse(LocalDateTime.now()).toLocalDate();long n=repo.countByTecnicoIdAndFechaProgramadaBetween(r.tecnicoId(),d.atStartOfDay(),d.plusDays(1).atStartOfDay());if(n>=6)throw new ReglaNegocioException("El técnico ya tiene el máximo de 6 OT para ese día");o.setTecnicoId(r.tecnicoId());o.setEstado(EstadoOrden.ASIGNADA);}
 private void reprogramar(OrdenTrabajo o,AccionRequest r){if(r.fecha()==null||r.fecha().toLocalDate().isBefore(LocalDate.now()))throw new ReglaNegocioException("La nueva fecha no puede ser anterior a hoy");if(o.getEstado()==EstadoOrden.ASIGNADA||o.getEstado()==EstadoOrden.ACEPTADA)o.setEstado(EstadoOrden.ASIGNADA);o.setFechaProgramada(r.fecha());if(o.getTecnicoId()!=null){long n=repo.countByTecnicoIdAndFechaProgramadaBetween(o.getTecnicoId(),r.fecha().toLocalDate().atStartOfDay(),r.fecha().toLocalDate().plusDays(1).atStartOfDay());if(n>=6)throw new ReglaNegocioException("El técnico ya tiene el máximo de 6 OT para ese día");}}
 private TipoEvento tipo(AccionOrden a){return TipoEvento.valueOf(a.name());} private int sla(Prioridad p){return switch(p){case URGENTE->4;case ALTA->8;case MEDIA->24;case BAJA->72;};} private String siguiente(){long n=repo.findTopByOrderByIdDesc().map(o->o.getId()+1).orElse(1L);return String.format("OT-%04d",n);} private OrdenTrabajo get(Long id){return repo.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Orden no encontrada"));} private boolean visible(OrdenTrabajo o,ActorFilter f){return f.rol.equals("ADMINISTRADOR")||f.rol.equals("JEFATURA")||(f.rol.equals("CLIENTE")&&f.id.equals(o.getClienteId()))||(f.rol.equals("TECNICO")&&f.id.equals(o.getTecnicoId()));} public record ActorFilter(Long id,String rol){}
 public OrdenResponse dto(OrdenTrabajo o){return new OrdenResponse(o.getId(),o.getCodigo(),o.getClienteId(),o.getEquipoId(),o.getTipoServicio(),o.getPrioridad(),o.getEstado(),o.getTecnicoId(),o.getCreadoPorId(),o.getFechaProgramada(),o.getDescripcion(),o.getComentarioCliente(),o.getSlaHoras(),o.getCheckInEn(),o.getCheckOutEn(),o.getDiagnostico(),o.getActividades(),o.getMateriales(),o.getCreadoEn(),o.getModificadoEn());}
 public MetricaResponse metricas(){List<OrdenTrabajo> l=repo.findAll();Map<String,Long> m=l.stream().collect(Collectors.groupingBy(o->o.getEstado().name(),Collectors.counting()));long fuera=l.stream().filter(o->o.getCreadoEn()!=null&&Duration.between(o.getCreadoEn(),LocalDateTime.now()).toHours()>o.getSlaHoras()&&o.getEstado()!=EstadoOrden.VALIDADA&&o.getEstado()!=EstadoOrden.CANCELADA).count();double promedio=l.stream().filter(o->o.getCheckInEn()!=null&&o.getCheckOutEn()!=null).mapToLong(o->Duration.between(o.getCheckInEn(),o.getCheckOutEn()).toMinutes()).average().orElse(0)/60.0;return new MetricaResponse(m,fuera,promedio);}
}
